import recommender
import ui_components


def _profile_settings(connection):
    """Edit the local user's name and focus without changing history or favorites."""
    user_id = database.get_current_user_id(connection)
    profile = database.get_user_profile(connection, user_id)
    name, directions = ui_components.render_profile_fields(
        profile.display_name, profile.directions, 'ww_profile')
    if st.button('Save profile', type='primary', key='ww_save_profile'):
        try:
            database.update_user_profile(connection, user_id, name, directions)
            st.session_state['ww_profile_saved'] = True
            st.rerun()
        except ValueError as error:
            st.error(str(error))
    if st.session_state.pop('ww_profile_saved', False):
        st.success('Profile saved.')
    _demo_history_settings(connection, user_id)


def _demo_history_settings(connection, user_id):
    """Remove only the local demo rows after an explicit confirmation checkbox."""
    st.subheader('Demo history')
    st.caption('Clearing removes your sample attendance and ratings. Your own feedback is kept.')
    confirmed = st.checkbox('I want to clear my demo history', key='ww_clear_history_confirm')
    if st.button('Clear my demo history', disabled=not confirmed, key='ww_clear_history'):
        count = database.clear_demo_history(connection, user_id)
        st.session_state['ww_history_cleared'] = count
        st.session_state['ww_feedback_open'] = False
        st.rerun()
    if 'ww_history_cleared' in st.session_state:
        count = st.session_state.pop('ww_history_cleared')
        st.success(f'Removed {count} demo activities.')


def _data_sources(connection, now):
    """Display public source counts and sanitized logs, and allow explicit refresh/reset."""
    st.subheader('Data sources')
    st.write('Unisport provides weekly courses; UniClubs provides student-club activities; '
             'City provides St.Gallen events. Placeholder series are invented demo examples.')
    counts = database.get_source_counts_df(connection)
    st.dataframe(counts, hide_index=True, width='stretch')
    for source in config.SOURCES:
        rows = counts.loc[counts['source'] == source]
        if rows.empty:
            st.caption(f'{source}: no stored activities.')
        else:
            row = rows.iloc[0]
            st.caption(f'{source}: {row["placeholder_series"]} of {row["series"]} '
                       'stored series are placeholders. Import origins appear below.')
    if st.button('Refresh event data', key='ww_refresh_sources'):
        with st.spinner('Refreshing event data…'):
            reports = importers.import_all(connection, categories.load_taxonomy(), now=now)
            database.delete_past_unconfirmed_events(connection, now)
        ui_components.clear_data_caches()
        st.session_state['ww_import_reports'] = reports
        st.rerun()
    for report in st.session_state.pop('ww_import_reports', []):
        message = f'{report["source"]} · {report["origin"]}: {report["message"]}'
        if report['outcome'] == 'ok':
            st.success(message)
        else:
            st.warning(message)
    st.subheader('Import history')
    st.dataframe(database.get_import_log_df(connection), hide_index=True, width='stretch')
    ui_components.render_reset_controls(connection)


def _model_results(results):
    """Show validation comparison, independent test metrics and forest feature importances."""
    sizes = results.attrs['split_sizes']
    st.caption(f'Stratified 80/10/10 split, seed {config.RANDOM_SEED}: '
               f'{sizes["train"]} training / {sizes["validation"]} validation / '
               f'{sizes["test"]} test rows. RobustScaler is fitted on training rows only.')
    st.dataframe(results, hide_index=True, width='stretch')
    st.pyplot(recommender.plot_model_comparison(results), alt='Validation F1 model comparison')
    winner = results.sort_values('val_f1', ascending=False, kind='stable').iloc[0]
    forest_f1 = results.loc[(results['model'] == 'Random Forest') & ~results['scaled'],
                            'val_f1'].iloc[0]
    scale = 'scaled' if winner['scaled'] else 'unscaled'
    st.write(f'Validation leader: {winner["model"]} ({scale}), macro F1 {winner["val_f1"]:.3f}.')
    if winner['model'] != 'Random Forest' and winner['val_f1'] > forest_f1:
        st.info('Another classifier leads on validation F1. WeekWise keeps Random Forest: '
                'it handles mixed features without scaling, is robust and exposes feature '
                'importances. This comparison documents the tradeoff.')
    st.subheader('Random Forest · held-out test set')
    st.caption('This unscaled, unweighted forest saw only the training split. The production '
               'forest uses all eligible rows and weights your genuine ratings fivefold.')
    metrics = results.attrs['test_metrics']
    for column, name in zip(st.columns(len(metrics)), metrics):
        column.metric(name.capitalize(), f'{metrics[name]:.3f}')
    st.caption('Precision, recall and F1 are macro averages; undefined scores are zero.')
    st.code(results.attrs['classification_report'], language=None)
    importances = pd.DataFrame(results.attrs['feature_importances'])
    st.pyplot(recommender.plot_feature_importances(importances), alt='Top ten forest features')
    st.caption('Feature importance describes this fitted model, not a causal effect.')


def _about_model(connection, now):
    """Evaluate only when this tab is opened and explain training rows and fallback honestly."""
    st.subheader('About the model')
    st.write('WeekWise predicts whether you would rate an activity at least four stars. '
             'It uses activity categories, time, duration, price, location, your focus and '
             'favorites, earlier category ratings and friends going. Private calendar entries '
             'are never training data. Not-attended activities are excluded.')
    st.write('A new or edited rating updates the model on its next use. Your genuine ratings '
             'receive five times the production training weight of synthetic or demo ratings. '
             'The course comparison below fits all ten variants without sample weights.')
    summary = database.get_training_summary(connection, now)
    for column, name in zip(st.columns(3), ('Synthetic', 'Demo', 'Yours')):
        column.metric(name + ' training rows', summary[name])
    st.write(f'{summary["Total"]} eligible ratings: {summary["Positive"]} positive (4–5 stars), '
             f'{summary["Total"] - summary["Positive"]} negative (1–3 stars).')
    cache_key = database.get_rating_cache_key(connection)
    if ui_components.cached_recommender(*cache_key).model is None:
        st.info('Heuristic fallback is active: more ratings from both classes are needed. '
                'Suggestions use focus, favorites and friends going.')
    with st.spinner('Comparing five classifiers…'):
        results = ui_components.cached_evaluation(*cache_key)
    st.caption(f'Positive label share: {results.attrs["positive_share"]:.1%}. '
               'Synthetic data illustrate the method; scores do not establish real-world quality.')
    if not results.attrs['available']:
        st.info('Comparison unavailable. ' + results.attrs['reason'])
        return
    _model_results(results)


def _about_weekwise():
    """Show the problem, sources, privacy and the project's actual AI-usage record."""
    st.subheader('About WeekWise')
    st.write(config.PROBLEM_STATEMENT)
    st.write('Activities come from Unisport, UniClubs and St.Gallen city listings. Demo sources '
             'and 60 synthetic students make the app usable offline; Data sources shows origins.')
    st.write('Your calendar stays local: private entries are read to find gaps and are never '
             'stored in the activity database or shared with friends. Calendar links and uploads '
             'are saved on this computer only when you choose Remember. Rankings are aggregates. '
             'WeekWise opens calendar export links; it never writes through a calendar API.')
    st.write('HSG · Fundamentals and Methods of Computer Science · Autumn 2026. '
             'Built by the WeekWise project team.')
    st.caption('Version ' + config.APP_VERSION)
    st.write('AI assisted development is documented below. No LLM or external AI service is '
             'called at runtime; recommendations use the local scikit-learn model.')
    usage = config.AI_USAGE_FILE.read_text(encoding='utf-8')
    with st.expander('AI_USAGE.md · development record'):
        st.markdown(usage)
        st.download_button('Download AI usage record', usage, file_name='AI_USAGE.md',
                           mime='text/markdown', key='ww_download_ai_usage')


def render_settings(connection, now=None):
    """Render five settings tabs, computing the model comparison only in its active tab."""
    now = config.local_now(now)
    start = datetime.combine(gaps.week_start(now), datetime.min.time())
    end = start + timedelta(days=config.DAYS_PER_WEEK)
    st.title('Settings & About')
    # Course: L04 – tracked tabs expose .open, so ordinary settings never run model evaluation.
    profile_tab, calendar_tab, data_tab, model_tab, about_tab = st.tabs(
        ['Profile', 'Calendar', 'Data sources', 'About the model', 'About WeekWise'],
        key='ww_settings_tab', on_change='rerun')
    with profile_tab:
        _profile_settings(connection)
    with calendar_tab:
        ui_components.render_calendar_controls(connection, start, end)
    with data_tab:
        _data_sources(connection, now)
    with model_tab:
        if model_tab.open:
            _about_model(connection, now)
    with about_tab:
        _about_weekwise()
    ui_components.render_sidebar_status()


try:
    render_settings(ui_components.cached_connection())
except (OSError, ValueError, KeyError, sqlite3.Error):
    st.error('Could not load settings. Please check your inputs and try again.')
